from rcb_client import Robot
from PIL import Image
import numpy as np
r=Robot(); ran=np.array(r.spec()['qpos']['range'])
def a(q): return np.clip((2*q-ran[:,0]-ran[:,1])/(ran[:,1]-ran[:,0]),-1,1)
for ankle in [-.85,-.7,-.55,-.25,0.0]:
 o=r.reset(images=False);q=np.array(o['proprio']['joint_pos']);q[[4,9]]=ankle
 for i in range(0,100,10):
  o=r.step('qpos',[a(q)]*10,images=['room_camera'] if i==90 else False)
  if i in [40,90] or o['done']:print(ankle,o['step'],o['done'],np.round(o['imu']['gravity'],2),np.round(o['proprio']['joint_pos'][2:5],2))
  if o['done']:break
 if not o['done']:Image.fromarray(o['images']['room_camera']).save(f'/app/ank{ankle}.png')
